import base64
import subprocess
import shutil
from pathlib import Path

LIB_RS = base64.b64decode("").decode()
ENGINE_PY = base64.b64decode("").decode()
GITIGNORE_ADD = base64.b64decode("CiMgLS0tIGFkZGVkIGJ5IHJuYTItZW5naW5lIGNsZWFudXAgLS0tCi90YXJnZXQvCl9fcHljYWNoZV9fLwoqLnB5YwpleHRyYWN0ZWRfZGlyLwpleHRyYWN0ZWRfZW5jX2Rpci8KZXh0cmFjdGVkX291dHB1dC8KZXh0cmFjdGVkX3JhbmRfZW5jLwpybmEyX21lbW9yeV9zdG9yZS8KdGVzdF9kaXIvCnRlc3Rfc2FtcGxlX2RhdGEvCnJlbGVhc2UvCioucm5hMgpybmEyX3BtLmRsbAo=").decode()

repo_root = Path.cwd()
print(f"Working in: {repo_root}")
print()

def write_file(rel_path, content):
    p = repo_root / rel_path
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding="utf-8", newline="\n")
    print(f"[write] {rel_path} ({len(content)} bytes)")

def run(cmd, quiet_fail=True):
    result = subprocess.run(cmd, cwd=repo_root, capture_output=True, text=True)
    if result.returncode != 0 and not quiet_fail:
        print(f"        {result.stderr.strip()}")
    return result

# --- sanity check: are we actually in the rna2-engine folder? ---
if not (repo_root / "Cargo.toml").exists() or not (repo_root / "src").exists():
    print("[ERROR] This doesn't look like the rna2-engine folder (no Cargo.toml / src here).")
    print(f"        Run this from inside the repo folder, e.g.:")
    print(f"        cd 'C:\\Users\\Administrator\\Desktop\\rna2 Package manager'")
    raise SystemExit(1)

# 1. Replace the stub Rust core with the real implementation
write_file("src/lib.rs", LIB_RS)

# 2. Replace the stale Python wrapper with one matching the real exports
write_file("rna2_engine.py", ENGINE_PY)

# 3. Extend .gitignore
gi_path = repo_root / ".gitignore"
existing = gi_path.read_text(encoding="utf-8") if gi_path.exists() else ""
if "added by rna2-engine cleanup" not in existing:
    gi_path.write_text(existing.rstrip() + "\n" + GITIGNORE_ADD, encoding="utf-8", newline="\n")
    print("[write] .gitignore (appended cleanup rules)")
else:
    print("[skip]  .gitignore already updated")

# 4. Untrack committed build/test artifacts (keeps files on disk, just stops tracking them in git)
is_git_repo = (repo_root / ".git").exists()
paths_to_untrack = [
    "__pycache__", "target", "extracted_dir", "extracted_enc_dir",
    "extracted_output", "extracted_rand_enc", "rna2_memory_store",
    "test_dir", "test_sample_data", "release",
    "auto_pruned_block_1.rna2", "c_abi_test_block.rna2", "cli_sample.txt",
    "cli_test.rna2", "context_block.rna2", "dir_archive.rna2",
    "enc_dir_archive.rna2", "plain_test.rna2", "plaintext_block.rna2",
    "rand_enc_archive.rna2", "secure.rna2", "test_vault.rna2", "test_output.rna2",
    "rna2_pm.dll",
]
if is_git_repo:
    print()
    for p in paths_to_untrack:
        if (repo_root / p).exists():
            run(["git", "rm", "-r", "--cached", "--quiet", p])
    print("[git]   untracked build/test artifacts (files stay on disk)")
else:
    print()
    print("[skip]  no .git folder found here -- skipping git cleanup step")

# 5. Rebuild the DLL with the real implementation, if cargo is available
print()
cargo = shutil.which("cargo")
if cargo:
    print("[cargo] building release DLL (this can take 30-90s the first time)...")
    result = subprocess.run(["cargo", "build", "--release"], cwd=repo_root, capture_output=True, text=True)
    if result.returncode == 0:
        built_dll = repo_root / "target" / "release" / "rna2_pm.dll"
        if built_dll.exists():
            shutil.copy2(built_dll, repo_root / "rna2_pm.dll")
            print("[write] rna2_pm.dll (copied fresh build to repo root)")
        else:
            print("[WARN]  build succeeded but didn't find target/release/rna2_pm.dll -- copy it manually")
    else:
        print("[ERROR] cargo build failed:")
        print(result.stderr[-2000:])
        print("        Fix the error above, then re-run: cargo build --release")
else:
    print("[skip]  'cargo' not found on PATH -- Rust toolchain isn't installed.")
    print("        Install it from https://rustup.rs, then run: cargo build --release")
    print("        and copy target\\release\\rna2_pm.dll to the repo root.")

print()
print("=" * 60)
print("Done.")
print("=" * 60)
print()
print("Recommended next steps:")
print("  1. python test_rna2.py       (or your usual smoke test -- confirm pack/unpack works)")
if is_git_repo:
    print("  2. git add -A && git status  (review -- artifacts should no longer show as new/modified)")
    print("  3. git commit -m \"Implement real pack/unpack (AES-256-GCM + zlib), fix ABI mismatch, clean up repo\"")
